{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2159-12-23 16:10:00",
      "speaker": "Doctor",
      "text": "Hello, I'm Dr. Lee. I’ll be helping take care of you during your stay. Can you tell me what brought you to the hospital?"
    },
    {
      "turn_number": 2,
      "time": "2159-12-23 16:11:00",
      "speaker": "Patient",
      "text": "Hi, Doctor. I’ve had dark, tarry stools for the past two days. I’m not in pain, but I’ve been feeling weak and tired."
    },
    {
      "turn_number": 3,
      "time": "2159-12-23 16:12:00",
      "speaker": "Doctor",
      "text": "I see. That can be a sign of bleeding in the digestive tract. We checked your blood and your hemoglobin was low at 8.0, so we gave you one unit of blood in the ER and will likely give more."
    },
    {
      "turn_number": 4,
      "time": "2159-12-23 16:13:00",
      "speaker": "Patient",
      "text": "Oh, that makes sense. I’ve been dizzy too. Is it serious?"
    },
    {
      "turn_number": 5,
      "time": "2159-12-23 16:14:00",
      "speaker": "Doctor",
      "text": "It’s concerning, especially with your medical history. You’re on warfarin for your mechanical heart valve, so we have to be careful. We’ve stopped the warfarin for now and started an IV heparin drip to keep your blood thin but reduce bleeding risk."
    },
    {
      "turn_number": 6,
      "time": "2159-12-23 16:15:00",
      "speaker": "Patient",
      "text": "Okay, that sounds scary. Will I need surgery?"
    },
    {
      "turn_number": 7,
      "time": "2159-12-23 16:16:00",
      "speaker": "Doctor",
      "text": "Not right now. We’re going to do an upper endoscopy today to look in your stomach and upper intestine. A colonoscopy is scheduled for tomorrow to check your colon."
    },
    {
      "turn_number": 8,
      "time": "2159-12-23 16:17:00",
      "speaker": "Patient",
      "text": "Alright. And my dialysis? I do it five times a week at home."
    },
    {
      "turn_number": 9,
      "time": "2159-12-23 16:18:00",
      "speaker": "Doctor",
      "text": "We’ve coordinated with renal. You’ll get dialysis here while you’re in the hospital. They’ll help manage your fluids and electrolytes."
    },
    {
      "turn_number": 10,
      "time": "2159-12-23 16:19:00",
      "speaker": "Patient",
      "text": "Good. My blood pressure’s been all over the place lately."
    },
    {
      "turn_number": 11,
      "time": "2159-12-23 16:20:00",
      "speaker": "Doctor",
      "text": "Yes, we saw your BP was high earlier—190 over 63. We gave you labetalol. Since your home meds were stopped due to low pressures during dialysis, we’re restarting them carefully."
    },
    {
      "turn_number": 12,
      "time": "2159-12-23 16:21:00",
      "speaker": "Patient",
      "text": "I’ve had so many changes. It’s hard to keep track."
    },
    {
      "turn_number": 13,
      "time": "2159-12-23 16:22:00",
      "speaker": "Doctor",
      "text": "We’ll go over everything before you leave. For now, focus on resting. The GI team will be in soon for your endoscopy."
    },
    {
      "turn_number": 14,
      "time": "2159-12-24 09:00:00",
      "speaker": "Doctor",
      "text": "Good morning. How are you feeling?"
    },
    {
      "turn_number": 15,
      "time": "2159-12-24 09:01:00",
      "speaker": "Patient",
      "text": "A little better. The scope yesterday didn’t find anything, right?"
    },
    {
      "turn_number": 16,
      "time": "2159-12-24 09:02:00",
      "speaker": "Doctor",
      "text": "That’s correct. The EGD showed some mild irritation in your duodenum—duodenitis—but no active bleeding. The colonoscopy is scheduled for today."
    },
    {
      "turn_number": 17,
      "time": "2159-12-24 09:03:00",
      "speaker": "Patient",
      "text": "What’s duodenitis? Is that why I’m bleeding?"
    },
    {
      "turn_number": 18,
      "time": "2159-12-24 09:04:00",
      "speaker": "Doctor",
      "text": "It’s inflammation in the first part of your small intestine. It can cause bleeding, but we didn’t see any active source. We’ll check your colon today and may do a capsule study if needed."
    },
    {
      "turn_number": 19,
      "time": "2159-12-24 09:05:00",
      "speaker": "Patient",
      "text": "Okay. And my blood? Did it improve?"
    },
    {
      "turn_number": 20,
      "time": "2159-12-24 09:06:00",
      "speaker": "Doctor",
      "text": "Your hemoglobin went up to 8.5 after the second unit of blood. We’re giving a third unit today to stabilize it further."
    },
    {
      "turn_number": 21,
      "time": "2159-12-24 09:07:00",
      "speaker": "Patient",
      "text": "Thank you. I feel less shaky already."
    },
    {
      "turn_number": 22,
      "time": "2159-12-25 10:00:00",
      "speaker": "Doctor",
      "text": "The colonoscopy was completed. It showed angioectasia in your cecum—small abnormal blood vessels—and some polyps in the rectum."
    },
    {
      "turn_number": 23,
      "time": "2159-12-25 10:01:00",
      "speaker": "Patient",
      "text": "Did they stop the bleeding?"
    },
    {
      "turn_number": 24,
      "time": "2159-12-25 10:02:00",
      "speaker": "Doctor",
      "text": "There was no active bleeding. The polyps were small and not bleeding. The angioectasia could be the source, but it’s not bleeding now. We’ll do a capsule study to look at your small intestine."
    },
    {
      "turn_number": 25,
      "time": "2159-12-25 10:03:00",
      "speaker": "Patient",
      "text": "How does that work?"
    },
    {
      "turn_number": 26,
      "time": "2159-12-25 10:04:00",
      "speaker": "Doctor",
      "text": "You’ll swallow a small pill-sized camera that takes pictures as it moves through your gut. It’ll help us see if there’s any bleeding higher up."
    },
    {
      "turn_number": 27,
      "time": "2159-12-25 10:05:00",
      "speaker": "Patient",
      "text": "Alright. And my warfarin? When can I restart it?"
    },
    {
      "turn_number": 28,
      "time": "2159-12-25 10:06:00",
      "speaker": "Doctor",
      "text": "We’re keeping the heparin drip going for now. Once we’re sure the bleeding has stopped, we’ll restart warfarin. Your mechanical valve means we can’t stop blood thinners for long."
    },
    {
      "turn_number": 29,
      "time": "2159-12-26 08:30:00",
      "speaker": "Doctor",
      "text": "Good news—the capsule study didn’t show any active bleeding. It’s likely the bleed stopped on its own."
    },
    {
      "turn_number": 30,
      "time": "2159-12-26 08:31:00",
      "speaker": "Patient",
      "text": "That’s a relief. Can I go home soon?"
    },
    {
      "turn_number": 31,
      "time": "2159-12-26 08:32:00",
      "speaker": "Doctor",
      "text": "Not quite yet. We need to restart your warfarin and make sure your INR starts to rise. It’s still low at 1.8. We want it between 2.5 and 3.5 for your valve."
    },
    {
      "turn_number": 32,
      "time": "2159-12-26 08:33:00",
      "speaker": "Patient",
      "text": "I remember. I had a stroke before, so I can’t afford a clot."
    },
    {
      "turn_number": 33,
      "time": "2159-12-26 08:34:00",
      "speaker": "Doctor",
      "text": "Exactly. We’ve started warfarin again and will keep the heparin until your INR is in range."
    },
    {
      "turn_number": 34,
      "time": "2159-12-27 11:30:00",
      "speaker": "Doctor",
      "text": "We placed a temporary dialysis catheter in your neck today because your usual access isn’t working. It’ll make dialysis easier while you’re here."
    },
    {
      "turn_number": 35,
      "time": "2159-12-27 11:31:00",
      "speaker": "Patient",
      "text": "Is it safe? I’ve had infections before."
    },
    {
      "turn_number": 36,
      "time": "2159-12-27 11:32:00",
      "speaker": "Doctor",
      "text": "We used ultrasound and sterile technique. The risk is low, and we’ll remove it once you’re back on home dialysis."
    },
    {
      "turn_number": 37,
      "time": "2159-12-28 09:00:00",
      "speaker": "Doctor",
      "text": "Your INR is now 2.0—still a bit low, but moving in the right direction. We’ll keep monitoring it."
    },
    {
      "turn_number": 38,
      "time": "2159-12-28 09:01:00",
      "speaker": "Patient",
      "text": "I’m feeling stronger. Can I walk a bit?"
    },
    {
      "turn_number": 39,
      "time": "2159-12-28 09:02:00",
      "speaker": "Doctor",
      "text": "Yes, with your walker. Just take it slow. Your leg wounds are healing, but the ulcer on your right heel needs care."
    },
    {
      "turn_number": 40,
      "time": "2159-12-29 10:00:00",
      "speaker": "Doctor",
      "text": "Your hemoglobin is stable at 8.5. No more blood needed. We’re down to one unit of heparin and warfarin is working."
    },
    {
      "turn_number": 41,
      "time": "2159-12-29 10:01:00",
      "speaker": "Patient",
      "text": "Great. What about my blood pressure meds?"
    },
    {
      "turn_number": 42,
      "time": "2159-12-29 10:02:00",
      "speaker": "Doctor",
      "text": "We’ve increased your labetalol to 300 mg three times a day. It’s helping. Keep taking it until your nephrologist adjusts it with home dialysis."
    },
    {
      "turn_number": 43,
      "time": "2159-12-30 08:00:00",
      "speaker": "Doctor",
      "text": "Your INR is 2.2 today—still below goal, but you’re improving. We’ve stopped the heparin."
    },
    {
      "turn_number": 44,
      "time": "2159-12-30 08:01:00",
      "speaker": "Patient",
      "text": "Can I go home? I promise to follow up."
    },
    {
      "turn_number": 45,
      "time": "2159-12-30 08:02:00",
      "speaker": "Doctor",
      "text": "We’d prefer to keep you until your INR is in range, but we understand. If you go home, you must check your INR at your next dialysis and call the results in."
    },
    {
      "turn_number": 46,
      "time": "2159-12-30 08:03:00",
      "speaker": "Patient",
      "text": "I will. I’ll take the 7 mg warfarin dose you prescribed."
    },
    {
      "turn_number": 47,
      "time": "2159-12-30 08:04:00",
      "speaker": "Doctor",
      "text": "Good. Also, keep taking pantoprazole for stomach protection, and restart aspirin as listed."
    },
    {
      "turn_number": 48,
      "time": "2159-12-31 09:00:00",
      "speaker": "Doctor",
      "text": "You’re cleared for discharge tomorrow. Your dialysis is scheduled for the day after, then home sessions resume."
    },
    {
      "turn_number": 49,
      "time": "2159-12-31 09:01:00",
      "speaker": "Patient",
      "text": "Thank you. What should I watch for at home?"
    },
    {
      "turn_number": 50,
      "time": "2159-12-31 09:02:00",
      "speaker": "Doctor",
      "text": "Call if you see black stools again, feel dizzy, or your weight goes up more than 3 pounds in a day. That could mean fluid overload."
    },
    {
      "turn_number": 51,
      "time": "2159-12-31 09:03:00",
      "speaker": "Patient",
      "text": "I weigh myself every morning. I’ll keep doing that."
    },
    {
      "turn_number": 52,
      "time": "2159-12-31 09:04:00",
      "speaker": "Doctor",
      "text": "Perfect. You also have follow-up with vascular surgery for your prosthetic and with GI in a few weeks."
    },
    {
      "turn_number": 53,
      "time": "2159-12-31 09:05:00",
      "speaker": "Patient",
      "text": "And my kidney doctor?"
    },
    {
      "turn_number": 54,
      "time": "2159-12-31 09:06:00",
      "speaker": "Doctor",
      "text": "Yes, touch base with them at your next dialysis. They’ll help adjust your blood pressure meds."
    },
    {
      "turn_number": 55,
      "time": "2160-01-01 08:00:00",
      "speaker": "Doctor",
      "text": "Good morning. We’re finalizing your discharge. Your INR is still 2.2, but you’re stable."
    },
    {
      "turn_number": 56,
      "time": "2160-01-01 08:01:00",
      "speaker": "Patient",
      "text": "I’m ready to go home. I’ll follow all the instructions."
    },
    {
      "turn_number": 57,
      "time": "2160-01-01 08:02:00",
      "speaker": "Doctor",
      "text": "You’re doing well. Take the warfarin as directed, check your INR, and call your PCP to set up a follow-up."
    },
    {
      "turn_number": 58,
      "time": "2160-01-01 08:03:00",
      "speaker": "Patient",
      "text": "I’ll do that. Thank you for taking care of me."
    },
    {
      "turn_number": 59,
      "time": "2160-01-01 08:04:00",
      "speaker": "Doctor",
      "text": "You’re welcome. We’ll see you in follow-up. Get some rest and take care."
    },
    {
      "turn_number": 60,
      "time": "2160-01-01 08:05:00",
      "speaker": "Patient",
      "text": "I will. Thank you again."
    },
    {
      "turn_number": 61,
      "time": "2160-01-01 10:00:00",
      "speaker": "Doctor",
      "text": "Just a quick check before you leave. Any questions?"
    },
    {
      "turn_number": 62,
      "time": "2160-01-01 10:01:00",
      "speaker": "Patient",
      "text": "No, I think I’ve got it all. Medications, INR check, dialysis, and follow-ups."
    },
    {
      "turn_number": 63,
      "time": "2160-01-01 10:02:00",
      "speaker": "Doctor",
      "text": "Perfect. You’re doing great. Take care and we’ll see you soon."
    },
    {
      "turn_number": 64,
      "time": "2160-01-01 10:03:00",
      "speaker": "Patient",
      "text": "Thank you, Doctor."
    },
    {
      "turn_number": 65,
      "time": "2160-01-01 12:00:00",
      "speaker": "Doctor",
      "text": "The discharge team is ready to take you home. Your husband is here, right?"
    },
    {
      "turn_number": 66,
      "time": "2160-01-01 12:01:00",
      "speaker": "Patient",
      "text": "Yes, he’s in the waiting area. I’m so glad to be going home."
    },
    {
      "turn_number": 67,
      "time": "2160-01-01 12:02:00",
      "speaker": "Doctor",
      "text": "You’ve worked hard. Keep up the good care. Call us if anything changes."
    },
    {
      "turn_number": 68,
      "time": "2160-01-01 12:03:00",
      "speaker": "Patient",
      "text": "I will. Thank you for everything."
    },
    {
      "turn_number": 69,
      "time": "2160-01-01 12:04:00",
      "speaker": "Doctor",
      "text": "Take care. See you soon."
    },
    {
      "turn_number": 70,
      "time": "2160-01-01 12:05:00",
      "speaker": "Patient",
      "text": "Bye, Doctor."
    },
    {
      "turn_number": 71,
      "time": "2160-01-01 14:00:00",
      "speaker": "Doctor",
      "text": "Just calling to confirm you got home safely."
    },
    {
      "turn_number": 72,
      "time": "2160-01-01 14:01:00",
      "speaker": "Patient",
      "text": "Yes, we’re home. I’m resting now."
    },
    {
      "turn_number": 73,
      "time": "2160-01-01 14:02:00",
      "speaker": "Doctor",
      "text": "Good. Remember to take your warfarin tomorrow and get the INR checked at dialysis."
    },
    {
      "turn_number": 74,
      "time": "2160-01-01 14:03:00",
      "speaker": "Patient",
      "text": "I won’t forget. Thank you for checking in."
    },
    {
      "turn_number": 75,
      "time": "2160-01-01 14:04:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Take care."
    },
    {
      "turn_number": 76,
      "time": "2160-01-01 16:00:00",
      "speaker": "Doctor",
      "text": "Final call. Your discharge summary has been sent to your PCP and nephrologist."
    },
    {
      "turn_number": 77,
      "time": "2160-01-01 16:01:00",
      "speaker": "Patient",
      "text": "Thank you. I’ll make sure they get it."
    },
    {
      "turn_number": 78,
      "time": "2160-01-01 16:02:00",
      "speaker": "Doctor",
      "text": "You’re all set. Rest well and we’ll see you in follow-up."
    },
    {
      "turn_number": 79,
      "time": "2160-01-01 16:03:00",
      "speaker": "Patient",
      "text": "I will. Thank you again."
    },
    {
      "turn_number": 80,
      "time": "2160-01-01 16:04:00",
      "speaker": "Doctor",
      "text": "Take care."
    },
    {
      "turn_number": 81,
      "time": "2160-01-01 16:05:00",
      "speaker": "Patient",
      "text": "Bye."
    },
    {
      "turn_number": 82,
      "time": "2160-01-01 18:00:00",
      "speaker": "Doctor",
      "text": "Just confirming you’re settled. Any issues?"
    },
    {
      "turn_number": 83,
      "time": "2160-01-01 18:01:00",
      "speaker": "Patient",
      "text": "No, everything’s fine. I took my meds and I’m feeling okay."
    },
    {
      "turn_number": 84,
      "time": "2160-01-01 18:02:00",
      "speaker": "Doctor",
      "text": "Great. Call anytime if you need us."
    },
    {
      "turn_number": 85,
      "time": "2160-01-01 18:03:00",
      "speaker": "Patient",
      "text": "I will. Thank you, Doctor."
    }
  ],
  "summary": {
    "admission_start": "2159-12-23 16:08:00",
    "admission_end": "2160-01-01 18:40:00",
    "summary_paragraph": "A woman with end-stage renal disease on home hemodialysis, a mechanical aortic valve on anticoagulation, chronic diastolic heart failure, and peripheral vascular disease was admitted for dark, tarry stools and weakness. She was found to have acute blood loss anemia with a hemoglobin of 8.0 g/dL and received three units of packed red blood cells. Evaluation with esophagogastroduodenoscopy, colonoscopy, and capsule endoscopy did not identify an active bleeding source, though angioectasia and polyps were noted. Warfarin was held and a heparin drip initiated, later transitioned back to warfarin. Her INR remained subtherapeutic at 2.2 at discharge, but she elected to leave with close outpatient follow-up. Hypertension was managed with increased labetalol, and dialysis was continued inpatient. She was discharged home with services, instructions to monitor for recurrent bleeding, check INR at dialysis, and follow up with vascular surgery and gastroenterology.",
    "problems": [
      "Hemorrhage of gastrointestinal tract, unspecified",
      "End stage renal disease",
      "Acute posthemorrhagic anemia",
      "Chronic diastolic heart failure",
      "Hypertension",
      "Heart valve replaced by other means",
      "Long-term (current) use of anticoagulants",
      "Peripheral vascular disease, unspecified",
      "Duodenitis, without mention of hemorrhage",
      "Angiodysplasia of intestine (without mention of hemorrhage)",
      "Diverticulosis of colon (without mention of hemorrhage)",
      "Anal and rectal polyp"
    ]
  }
}
